:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #173b39;
  background: #e9f2ec;
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background-color: #e9f2ec;
  background-image: linear-gradient(30deg, #dce9df 12%, transparent 12.5%, transparent 87%, #dce9df 87.5%, #dce9df), linear-gradient(150deg, #dce9df 12%, transparent 12.5%, transparent 87%, #dce9df 87.5%, #dce9df), linear-gradient(30deg, #dce9df 12%, transparent 12.5%, transparent 87%, #dce9df 87.5%, #dce9df), linear-gradient(150deg, #dce9df 12%, transparent 12.5%, transparent 87%, #dce9df 87.5%, #dce9df);
  background-size: 56px 98px;
  background-position: 0 0, 0 0, 28px 49px, 28px 49px;
}

.card {
  width: min(100%, 620px);
  padding: clamp(24px, 6vw, 44px);
  border: 2px solid #173b39;
  border-radius: 18px;
  background: #fffdf5;
  box-shadow: 8px 8px 0 #173b39;
  text-align: center;
}

.pixel-mark {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  margin: 0 auto 14px;
  border: 2px solid #173b39;
  border-radius: 10px;
  background: #f5bd5b;
  font-size: 28px;
  font-weight: 800;
}
.eyebrow, .exact-label { margin: 0; color: #52716a; font-size: .78rem; font-weight: 800; letter-spacing: .12em; }
h1 { margin: 8px 0; font-size: clamp(1.8rem, 6vw, 2.5rem); line-height: 1.1; }
.intro { margin: 0 auto 28px; color: #52716a; line-height: 1.5; }

.fractions { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 14px; }
.fraction, .operations { min-width: 0; margin: 0; padding: 16px; border: 1px solid #b8cdc0; border-radius: 12px; }
.fraction legend, .operations legend { padding: 0 6px; font-weight: 700; }
.fraction label { display: block; margin: 5px 0; color: #52716a; font-size: .88rem; }
.fraction input {
  width: 100%; min-height: 46px; padding: 8px;
  border: 1px solid #8ca99a; border-radius: 8px;
  background: #fff; color: #173b39; font: inherit; text-align: center;
}
.fraction input:focus-visible, button:focus-visible { outline: 3px solid #d68a25; outline-offset: 3px; }
.fraction-line { display: block; height: 2px; margin: 7px 4px; background: #173b39; }
.between { color: #52716a; font-size: .9rem; }
.operations { margin-top: 24px; }
.operation-buttons { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
button {
  min-height: 52px; border: 2px solid #173b39; border-radius: 10px;
  background: #d7e9dc; color: #173b39; font: inherit; font-size: 1.55rem; font-weight: 750; cursor: pointer;
  transition: transform .12s ease, background-color .12s ease, box-shadow .12s ease;
}
button:hover { background: #f5bd5b; transform: translateY(-2px); }
button:active { transform: translateY(1px); box-shadow: inset 0 2px 3px #173b3940; }
button[aria-pressed="true"] { background: #f5bd5b; box-shadow: inset 0 0 0 2px #fffdf5; }
.result { margin-top: 26px; padding: 20px 16px; border-radius: 12px; background: #173b39; color: #fffdf5; }
.result h2 { margin: 0 0 8px; font-size: 1rem; }
.status { margin: 0; color: #d7e9dc; }
.status.error { color: #ffd28a; font-weight: 700; }
.answer { margin-top: 14px; }
.exact-label { color: #b8cdc0; }
.exact { margin: 5px 0 10px; font-size: 2rem; font-weight: 800; }
.decimal-label { margin: 0; color: #d7e9dc; }
.decimal-label span { color: #f5bd5b; font-weight: 750; }
.footnote { margin: 20px 0 0; color: #52716a; font-size: .85rem; }

@media (max-width: 440px) {
  .card { padding: 24px 18px; }
  .fractions { gap: 8px; }
  .fraction { padding: 12px 9px; }
  .between { font-size: .8rem; }
  .operation-buttons { gap: 7px; }
}

const form = document.querySelector('#calculator');
const status = document.querySelector('#status');
const answer = document.querySelector('#answer');
const exact = document.querySelector('#exact');
const decimal = document.querySelector('#decimal');
const buttons = [...document.querySelectorAll('[data-op]')];
let selectedOperation = null;

function gcd(a, b) {
  a = Math.abs(a);
  b = Math.abs(b);
  while (b) [a, b] = [b, a % b];
  return a || 1;
}

function readInteger(id) {
  const field = document.getElementById(id);
  const value = field.value.trim();
  if (value === '' || !Number.isSafeInteger(Number(value))) {
    field.focus();
    throw new Error('Enter a whole number in every field.');
  }
  return Number(value);
}

function calculate(operation) {
  answer.hidden = true;
  status.classList.remove('error');
  try {
    let a = readInteger('n1');
    let b = readInteger('d1');
    let c = readInteger('n2');
    let d = readInteger('d2');
    if (b === 0 || d === 0) throw new Error('Denominators cannot be zero.');
    if (b < 0) { a = -a; b = -b; }
    if (d < 0) { c = -c; d = -d; }

    let numerator;
    let denominator;
    if (operation === '+') { numerator = a * d + c * b; denominator = b * d; }
    if (operation === '-') { numerator = a * d - c * b; denominator = b * d; }
    if (operation === '*') { numerator = a * c; denominator = b * d; }
    if (operation === '/') {
      if (c === 0) throw new Error('Cannot divide by a fraction equal to zero.');
      numerator = a * d;
      denominator = b * c;
    }
    if (denominator < 0) { numerator = -numerator; denominator = -denominator; }
    const divisor = gcd(numerator, denominator);
    numerator /= divisor;
    denominator /= divisor;
    exact.textContent = denominator === 1 ? String(numerator) : `${numerator} / ${denominator}`;
    decimal.textContent = (numerator / denominator).toFixed(3);
    answer.hidden = false;
    status.textContent = 'Calculation complete.';
  } catch (error) {
    status.textContent = error.message;
    status.classList.add('error');
  }
}

buttons.forEach(button => {
  button.addEventListener('click', () => {
    selectedOperation = button.dataset.op;
    buttons.forEach(item => item.setAttribute('aria-pressed', String(item === button)));
    calculate(selectedOperation);
  });
});

form.addEventListener('input', () => {
  if (selectedOperation) calculate(selectedOperation);
});
